fn overlapping<'a>(plan: &'a Value, window: (&str, &str)) -> Vec<&'a Value> {
    plan["plan"]["steps"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|step| step["static_anchor"] == false)
