/// What the event's colour decided.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CapturedPlacement {
    /// A coloured event, or one UbU cannot own: pinned to the event's own window.
    Static,
    /// An uncoloured event: the planner decides when. Only the event's length is
    /// kept, as a fixed duration; its start time is discarded.
    Dynamic { seconds: u64 },
}

#[derive(Debug, Clone, PartialEq)]
pub struct CapturedTask {
    /// None for a new source: allocation belongs to admission, keeping planning pure.
    pub task_id: Option<String>,
    pub origin_event_id: String,
    pub title: String,
    pub description: Option<String>,
    /// The event's own window. A Static Task is pinned to it. For a Dynamic Task
    /// it is only what the applied record remembers of the event.
    pub start_at: String,
    pub end_at: String,
    pub placement: CapturedPlacement,
    pub occupies_capacity: bool,
    pub category_tag: Option<String>,
}

/// One ownership rule and one operator-facing reason for capture and reconciliation.
pub fn not_ownable_diagnostic(external_id: &str) -> Option<DiagnosticBody> {
    external_id_for("", Some(external_id)).is_none().then(|| DiagnosticBody {
        code: "capture_event_not_ownable".into(),
        message: format!("Calendar event `{external_id}` cannot be captured: its id cannot be a UbU Task handle, so UbU cannot own it"),
    })
}

/// How many unowned events one capture names before it counts the rest.
pub const MAX_OCCUPANCY_NAMED: usize = 3;

/// One diagnostic for every event of a capture that UbU cannot own, in the shape
/// `suggest_tags::skipped_occurrences` uses: the first few are named and the rest
/// are counted. A week of a daily commitment is one line, not seven. Ids only:
/// an event's title is never echoed.
pub fn occupancy_diagnostic(ids: &[String]) -> Option<DiagnosticBody> {
    let message = match ids {
        [] => return None,
        [id] => format!("Calendar event `{id}` cannot be owned by UbU, so its time is recorded as an occupied window that UbU will never write back to or export"),
        _ => {
            let named: Vec<_> = ids.iter().take(MAX_OCCUPANCY_NAMED).map(|id| format!("`{id}`")).collect();
            let rest = match ids.len() - named.len() {
                0 => String::new(),
                more => format!(" and {more} more"),
            };
            format!(
                "{} Calendar events cannot be owned by UbU, so the time of each is recorded as an occupied window that UbU will never write back to or export: {}{rest}",
                ids.len(),
                named.join(", ")
            )
        }
    };
    Some(DiagnosticBody { code: "capture_occupancy_only".into(), message })
}

/// One diagnostic for every event of a capture that is UbU's own echo: an event UbU
/// minted, by its stamp, for a Task this store does not have. The same shape as
/// `occupancy_diagnostic`: the first few are named and the rest are counted. Ids
/// only: an event's title is never echoed.
pub fn stale_export_diagnostic(ids: &[String]) -> Option<DiagnosticBody> {
    let message = match ids {
        [] => return None,
        [id] => format!("Calendar event `{id}` was created by UbU for a Task this store does not have, so it is left alone and becomes no Task"),
        _ => {
            let named: Vec<_> = ids.iter().take(MAX_OCCUPANCY_NAMED).map(|id| format!("`{id}`")).collect();
            let rest = match ids.len() - named.len() {
                0 => String::new(),
                more => format!(" and {more} more"),
            };
            format!(
                "{} Calendar events were created by UbU for Tasks this store does not have, so each is left alone and becomes no Task: {}{rest}",
                ids.len(),
                named.join(", ")
            )
        }
    };
    Some(DiagnosticBody { code: "capture_stale_export".into(), message })
}

pub fn plan_capture(
    foreign: &[DesiredEvent],
    palette_inverse: &BTreeMap<String, Option<String>>,
    existing_by_source: &BTreeMap<String, String>,
    ubu_created_ids: &BTreeSet<String>,
) -> (Vec<CapturedTask>, Vec<DiagnosticBody>) {
    let mut tasks = Vec::new();
    let mut diagnostics = Vec::new();
    let mut seen = BTreeSet::new();
    let mut unowned = Vec::new();
    let mut stale = Vec::new();
    for event in foreign {
        if !seen.insert(&event.external_id) {
            continue;
        }
        // A foreign event reaches this function only when the store has neither an
        // applied record for it nor an active Task of that handle. A stamp UbU wrote
        // when it minted the event therefore means a store UbU no longer has: it is
        // UbU's own echo, not a commitment the operator made, and it becomes no Task.
        // An event this store already holds a Task for is not an echo, whatever it
        // carries: that is a captured Task following its event's colour.
        if ubu_created_ids.contains(&event.external_id) && !existing_by_source.contains_key(&event.external_id) {
            stale.push(event.external_id.clone());
            continue;
        }
        let window = CalendarTimeRange::parse(&event.start_at, &event.end_at);
        // An id UbU cannot own, such as a recurring instance, is still occupied
        // time. Record the occupancy without claiming the event: the Task gets a
        // minted handle, the Google id lives in provenance so a repeat capture
        // updates rather than duplicates, and `external_id_for` keeps it out of
        // every desired export set because its origin cannot round-trip.
        let ownable = not_ownable_diagnostic(&event.external_id).is_none();
        if window.is_err() || event.summary.trim().is_empty() {
            diagnostics.push(DiagnosticBody {
                code: "capture_event_invalid".into(),
                message: "Calendar event has an unusable title or concrete time span; skipped"
                    .into(),
            });
            continue;
        }
        let window = window.unwrap();
        // Whole planning seconds, as the canonical window below has them.
        let span_seconds = u64::try_from(window.end.inner().unix_timestamp() - window.start.inner().unix_timestamp()).unwrap_or(0);
        // Planning coordinates are whole UTC seconds; canonicalize both sides of the round trip.
        let times = [window.start, window.end].map(|timestamp| {
            u64::try_from(timestamp.inner().unix_timestamp())
                .ok()
                .and_then(|seconds| crate::planning_time::timestamp_at(seconds).ok())
        });
        let [Some(start_at), Some(end_at)] = times else {
            diagnostics.push(DiagnosticBody {
                code: "capture_event_invalid".into(),
                message: "Calendar event is outside the supported planning time range; skipped"
                    .into(),
            });
            continue;
        };
        if start_at >= end_at {
            diagnostics.push(DiagnosticBody {
                code: "capture_event_invalid".into(),
                message: "Calendar event must span at least one planning second; skipped".into(),
            });
            continue;
        }
        // The colour decides the placement, and only its absence makes work
        // Dynamic. A colour mapped to no category, or to several, is still a
        // colour: the event is a commitment whose category is merely unknown.
        let (placement, category_tag) = match &event.color_id {
            None if ownable => {
                diagnostics.push(DiagnosticBody { code: "capture_colour_absent".into(), message: format!("Calendar event `{}` has no colour, so it is taken as work for UbU to schedule: a Dynamic Task of the event's length, at no fixed time", event.external_id) });
                (CapturedPlacement::Dynamic { seconds: span_seconds }, None)
            }
            None => {
                diagnostics.push(DiagnosticBody { code: "capture_colour_absent".into(), message: format!("Calendar event `{}` has no colour, but UbU cannot own it and so cannot move it: it stays a commitment at its own time, with no category", event.external_id) });
                (CapturedPlacement::Static, None)
            }
            Some(color) => {
                let category = match palette_inverse.get(color) {
                    Some(Some(category)) => Some(category.clone()),
                    Some(None) => {
                        diagnostics.push(DiagnosticBody { code: "capture_colour_ambiguous".into(), message: format!("Calendar event `{}` has a colour shared by multiple categories; no category assigned", event.external_id) });
                        None
                    }
                    None => {
                        diagnostics.push(DiagnosticBody { code: "capture_colour_unmapped".into(), message: format!("Calendar event `{}` has unmapped colour `{color}`; no category assigned; map that colour in Settings to assign a category", event.external_id) });
                        None
                    }
                };
                (CapturedPlacement::Static, category)
            }
        };
        if !ownable {
            unowned.push(event.external_id.clone());
        }
        // A Dynamic Task that occupied nothing would be scheduled into a void, so
        // it always occupies capacity. A Free commitment that does not block is a
        // real distinction, and a Static capture keeps it.
        let occupies_capacity = match placement {
            CapturedPlacement::Static => !event.transparent,
            CapturedPlacement::Dynamic { .. } => true,
        };
        let (description, diagnostic) = super::calendar_wire::capture_description(&event.external_id, event.description.as_deref());
        diagnostics.extend(diagnostic.map(super::calendar_wire::list_diagnostic));
        tasks.push(CapturedTask {
            task_id: existing_by_source.get(&event.external_id).cloned(),
            origin_event_id: event.external_id.clone(),
            title: event.summary.clone(),
            description,
            start_at,
            end_at,
            placement,
            occupies_capacity,
            category_tag,
        });
    }
    // After the per-event colour diagnostics, and once each for the whole capture.
    diagnostics.extend(stale_export_diagnostic(&stale));
    diagnostics.extend(occupancy_diagnostic(&unowned));
    (tasks, diagnostics)

//! Pure Google Calendar request, response and status policy. No transport types.
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeSet;

use super::calendar_projection::DesiredEvent;

pub const CALENDAR_SCOPE: &str = "https://www.googleapis.com/auth/calendar";
pub const CALENDAR_API_BASE: &str = "https://www.googleapis.com/calendar/v3/calendars";
/// The private extended property UbU writes on an event it creates.
pub const UBU_TASK_PROPERTY: &str = "ubu_task";

// Field order and omission rules match quick-ubu/gcal's GoogleEventBody.
#[derive(Debug, Serialize)]
pub struct GoogleEventBody {
    pub summary: String,
    pub start: GoogleEventTime,
    pub end: GoogleEventTime,
    #[serde(rename = "colorId", skip_serializing_if = "Option::is_none")]
    pub color_id: Option<String>,
    pub transparency: String,
    pub reminders: GoogleReminders,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminders {
    #[serde(rename = "useDefault")]
    pub use_default: bool,
    pub overrides: Vec<GoogleReminder>,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminder {
    pub method: &'static str,
    // DesiredEvent uses i64; preserve it without narrowing or truncation.
    pub minutes: i64,
}

#[derive(Debug, Serialize)]
pub struct GoogleEventTime {
    #[serde(rename = "dateTime")]
    pub date_time: String,
}

pub fn event_body(event: &DesiredEvent) -> GoogleEventBody {
    GoogleEventBody {
        summary: event.summary.clone(),
        start: GoogleEventTime {
            date_time: event.start_at.clone(),
        },
        end: GoogleEventTime {
            date_time: event.end_at.clone(),
        },
        color_id: event.color_id.clone(),
        transparency: if event.transparent {
            "transparent"
        } else {
            "opaque"
        }
        .into(),
        reminders: GoogleReminders {
            use_default: false,
            overrides: event
                .reminders_minutes
                .iter()
                .map(|&minutes| GoogleReminder {
                    method: "popup",
                    minutes,
                })
                .collect(),
        },
    }
}

fn required_string<'a>(value: &'a Value, field: &str) -> Result<&'a str, String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("missing or invalid {field}"))
}

/// An all-day event has a date and no time, so it has no length. It cannot be a
/// Dynamic Task without inventing a duration, and a commitment with no time has
/// no window to pin. It is skipped, and the message says why.
pub const ALL_DAY_MESSAGE: &str = "all-day event has no dateTime; it carries no duration, so it cannot be scheduled and is skipped";

pub fn parse_event(value: &Value) -> Result<DesiredEvent, String> {
    parse_event_with_diagnostic(value).map(|(event, _)| event)
}

pub const DESCRIPTION_TOO_LARGE_CODE: &str = "capture_description_too_large";

fn description_limit_message() -> String {
    format!("description exceeds {} bytes; notes were not imported, but the event remains available for capture", super::clarify::MAX_DESCRIPTION_BYTES)
}

/// The same policy for Google input, normalized mock input and capture planning.
/// Whitespace is trimmed; markup and interior text are otherwise untouched.
pub fn capture_description(id: &str, raw: Option<&str>) -> (Option<String>, Option<String>) {
    let Some(text) = raw.map(str::trim).filter(|text| !text.is_empty()) else {
        return (None, None);
    };
    if text.len() > super::clarify::MAX_DESCRIPTION_BYTES {
        return (None, Some(format!("Calendar event `{id}`: {}", description_limit_message())));
    }
    (Some(text.to_owned()), None)
}

pub fn parse_event_with_diagnostic(value: &Value) -> Result<(DesiredEvent, Option<String>), String> {
    if value.get("status").and_then(Value::as_str) == Some("cancelled") {
        return Err("cancelled event".into());
    }
    let id = required_string(value, "id")?;
    let task_id = format!("task_{id}");
    let summary = required_string(value, "summary")?;
    let raw_description = match value.get("description") {
        None => None,
        Some(Value::String(text)) => Some(text.as_str()),
        _ => return Err("invalid description".into()),
    };
    let (description, description_diagnostic) = capture_description(id, raw_description);
    if value["start"].get("date").is_some() && value["start"].get("dateTime").is_none() {
        return Err(ALL_DAY_MESSAGE.into());
    }
    let start_at = required_string(&value["start"], "dateTime")?;
    let end_at = required_string(&value["end"], "dateTime")?;
    let start =
        chrono::DateTime::parse_from_rfc3339(start_at).map_err(|_| "invalid start.dateTime")?;
    let end = chrono::DateTime::parse_from_rfc3339(end_at).map_err(|_| "invalid end.dateTime")?;
    if end <= start {
        return Err("end.dateTime must follow start.dateTime".into());
    }
    let color_id = match value.get("colorId") {
        None => None,
        Some(Value::String(color)) => Some(color.clone()),
        _ => return Err("invalid colorId".into()),
    };
    // Like Quick UbU, an absent transparency means opaque.
    let transparent = match value.get("transparency") {
        None => false,
        Some(Value::String(transparency)) => transparency == "transparent",
        _ => return Err("invalid transparency".into()),
    };
    let reminders = &value["reminders"];
    // Default reminders are Calendar settings, not Task metadata. No explicit
    // reminder can be recovered from an omitted/default reminder specification.
    let explicit = match reminders.get("useDefault") {
        Some(Value::Bool(false)) => reminders.get("overrides"),
        Some(Value::Bool(true)) => None,
        None if reminders.is_null() => None,
        _ => return Err("invalid reminders.useDefault".into()),
    };
    let overrides = match explicit {
        None => &[][..], // Google may omit an empty overrides array.
        Some(Value::Array(overrides)) => overrides.as_slice(),
        _ => return Err("invalid reminders.overrides".into()),
    };
    let reminders_minutes = overrides
        .iter()
        .map(|reminder| {
            if reminder["method"] != "popup" {
                return Err("unsupported reminder method".into());
            }
            reminder["minutes"]
                .as_i64()
                .filter(|minutes| *minutes >= 0)
                .ok_or_else(|| "invalid reminder minutes".into())
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok((DesiredEvent {
        external_id: id.into(),
        task_id,
        summary: summary.into(),
        description,
        start_at: start_at.into(),
        end_at: end_at.into(),
        color_id,
        transparent,
        reminders_minutes,
    }, description_diagnostic))
}

pub fn parse_event_list(value: &Value) -> (Vec<DesiredEvent>, Vec<String>) {
    let Some(items) = value.get("items").and_then(Value::as_array) else {
        return (
            Vec::new(),
            vec!["list event `*`: missing or invalid items".into()],
        );
    };
    let mut events = Vec::new();
    let mut messages = Vec::new();
    for (index, item) in items.iter().enumerate() {
        match parse_event_with_diagnostic(item) {
            Ok((event, diagnostic)) => {
                events.push(event);
                messages.extend(diagnostic);
            }
            // Identify the entry by index and readable handle, never by its title or content.
            Err(message) => {
                let id = item.get("id").and_then(Value::as_str).unwrap_or("*");
                messages.push(format!("list event `{id}` entry {index}: {message}"));
            }
        }
    }
    (events, messages)
}

/// Ids of listed events UbU minted itself: the stamp is present and names the Task
/// whose handle the event id is. An event UbU only patched carries no stamp, and a
/// stamp that does not match the id is not evidence of minting.
///
/// Every absence yields fewer ids and never a failure: no `items`, no
/// `extendedProperties`, a `private` that is not an object, a stamp that is not a
/// string. `parse_event_list` reads the same JSON for the events themselves; this is
/// a second pass over it for where they came from.
pub fn ubu_created_ids(value: &Value) -> BTreeSet<String> {
    value
        .get("items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|item| {
            let id = item.get("id")?.as_str()?;
            let stamp = item
                .get("extendedProperties")?
                .get("private")?
                .get(UBU_TASK_PROPERTY)?
                .as_str()?;
            (stamp == format!("task_{id}")).then(|| id.to_owned())
        })
        .collect()
}

pub fn list_diagnostic(message: String) -> crate::api::planning::DiagnosticBody {
    crate::api::planning::DiagnosticBody {
        code: if message.ends_with(ALL_DAY_MESSAGE) { "capture_all_day_unsupported" } else if message.ends_with(&description_limit_message()) { DESCRIPTION_TOO_LARGE_CODE } else { "calendar_event_skipped" }.into(),
        message,
    }
}

fn percent_encode(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            encoded.push(char::from(byte));
        } else {
            use std::fmt::Write;
            write!(encoded, "%{byte:02X}").expect("writing to a String cannot fail");
        }
    }
    encoded
}

pub fn events_url(base: &str, calendar_id: &str, event_id: Option<&str>) -> String {
    let mut url = format!(
        "{}/{}/events",
        base.trim_end_matches('/'),
        percent_encode(calendar_id)
    );
    if let Some(id) = event_id {
        url.push('/');
        url.push_str(&percent_encode(id));
    }
    url
}

